 use serde :: { Deserialize , Serialize } ; use std :: collections :: HashMap ; # [doc = " Manages workspace dependencies in the root Cargo.toml."] pub fn manage_workspace_dependencies (root_cargo_toml_path : & Path , deps_to_add : & [(String , Value)] , dry_run : bool) -> Result < () > { # [derive (Debug , Default , serde :: Serialize , serde :: Deserialize)] struct Workspace { members : Option < Vec < String > > , # [serde (rename = "default-members")] default_members : Option < Vec < String > > , # [serde (default)] dependencies : HashMap < String , Value > , package : Option < toml :: Table > , lints : Option < toml :: Table > , } # [derive (Debug , serde :: Serialize , serde :: Deserialize)] struct CargoToml { workspace : Option < Workspace > , patch : Option < toml :: Table > , # [serde (flatten)] other : toml :: Table , } let cargo_toml_content = fs :: read_to_string (root_cargo_toml_path) . context (format ! ("Failed to read root Cargo.toml from {}" , root_cargo_toml_path . display ())) ? ; let mut cargo_toml : CargoToml = toml :: from_str (& cargo_toml_content) . context (format ! ("Failed to parse root Cargo.toml from {}" , root_cargo_toml_path . display ())) ? ; let workspace_ref = cargo_toml . workspace . get_or_insert_with (Default :: default) ; if workspace_ref . package . is_none () { workspace_ref . package = Some (get_default_workspace_package ()) ; } if workspace_ref . lints . is_none () { workspace_ref . lints = Some (toml :: Table :: new ()) ; } for (dep_name , dep_value) in deps_to_add { workspace_ref . dependencies . insert (dep_name . clone () , dep_value . clone ()) ; } let deps = & workspace_ref . dependencies ; let patches = cargo_toml . patch . get_or_insert_with (toml :: Table :: new) ; let crates_io_patches = patches . entry ("crates-io" . to_string ()) . or_insert_with (| | toml :: Value :: Table (toml :: Table :: new ())) . as_table_mut () . context ("crates-io patch must be a table") ? ; for (dep_name , dep_value) in deps . iter () { if let Some (dep_table) = dep_value . as_table () { if let Some (path_value) = dep_table . get ("path") { if let Some (path_str) = path_value . as_str () { let mut patch_entry = toml :: Table :: new () ; let resolved_path = resolve_crate_path_in_submodule (& PathBuf :: from (path_str) , dep_name) ? ; patch_entry . insert ("path" . to_string () , toml :: Value :: String (resolved_path . to_str () . context ("Resolved path is not valid UTF-8") ? . to_string ())) ; if let Some (package_name) = dep_table . get ("package") { patch_entry . insert ("package" . to_string () , package_name . clone ()) ; } crates_io_patches . insert (dep_name . clone () , toml :: Value :: Table (patch_entry)) ; } } } } let new_cargo_toml_content = toml :: to_string_pretty (& cargo_toml) . context ("Failed to serialize new root Cargo.toml") ? ; if dry_run { let new_path = root_cargo_toml_path . with_extension ("new") ; fs :: write (& new_path , new_cargo_toml_content) . context (format ! ("Failed to write new root Cargo.toml to {}" , new_path . display ())) ? ; println ! ("Dry-run: Generated new root Cargo.toml content to {} for workspace." , new_path . display ()) ; } else { fs :: write (root_cargo_toml_path , new_cargo_toml_content) . context (format ! ("Failed to write new root Cargo.toml to {}" , root_cargo_toml_path . display ())) ? ; println ! ("Successfully managed workspace dependencies in {}" , root_cargo_toml_path . display ()) ; } Ok (()) }